WITH eligible AS (SELECT s.* FROM orders s WHERE NOT EXISTS (SELECT 1 FROM shipments c WHERE c.order_id = s.id AND c.shipped_date >= s.order_date)) SELECT DATE_TRUNC('MONTH', order_date) AS activity_month, DATE_TRUNC('QUARTER', order_date) AS quarter_start, MAX(discount) AS max_discount, STDDEV_SAMP(shipping_fee) AS shipping_fee_stddev FROM eligible GROUP BY 1, 2 ORDER BY max_discount ASC NULLS LAST;
